mapper.select:
SELECT v.id,v.owner_id,v.item_id,i.kind,v.version_number AS number
FROM preparation_version v JOIN preparation_item i ON i.owner_id=v.owner_id AND i.id=v.item_id
WHERE v.owner_id=#{owner} AND v.item_id=#{itemId} AND v.id=#{versionId}

SELECT d.task_id,d.target_version_id,v.version_number AS target_version_number,d.created_at AS adopted_at,
  t.purpose,t.status AS task_status,t.manifest_json,t.manifest_hash,
  JSON_EXTRACT(t.candidate_json,'$.requirements[*].number') AS candidate_numbers_json,d.requirements_json
FROM ai_jd_requirement_decision d
JOIN preparation_version v ON v.owner_id=d.owner_id AND v.item_id=d.target_item_id AND v.id=d.target_version_id
JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id
WHERE d.owner_id=#{owner} AND d.target_item_id=#{itemId} AND d.status='ADOPTED' AND v.version_number <=#{through}
AND v.version_number < #{before}
ORDER BY v.version_number DESC LIMIT #{limit}
